<script type="text/javascript">
    jQuery(document).ready(function(){
        jQuery(document).on('click','#auto_add_etiqueta', function (event){
            if(jQuery('#modulo_id').val() != ""){
                var url_new = '<?php echo url_for('automatizacion_unidaddoc/newEtiqueta?modulo_id=') ?>'+jQuery('#modulo_id').val()
                javascript:jQuery.OpenModalSIMAD(url_new, "760", "480");
            }else{
                toastr.warning("Debes seleccionar el modulo de origen");
            }
        });

        jQuery(document).on('click','#auto_clear_etiqueta', function (event){
            jQuery('#auto_exp_etiqueta').select2('val', '').trigger('change');
        });

        jQuery('#texto_base, #separator_text').on('input change', function() {
            actualizarTextoMuestra();
        });

        jQuery('#auto_exp_etiqueta').on('change', function() {
            actualizarTextoMuestra();
        });

        function actualizarTextoMuestra() {
            var textoBase = jQuery('#texto_base').val().trim();
            var separador = jQuery('#separator_text').val();
            //var etiquetasSeleccionadas = jQuery('#auto_exp_etiqueta').val() || [];
            var etiquetasSeleccionadas = jQuery('#auto_exp_etiqueta').select2('data');            

            if (!textoBase && etiquetasSeleccionadas.length > 0) {
                jQuery('#texto_compuesto').val('');
                toastr.warning("Debes establecer el texto base");
                jQuery('#auto_exp_etiqueta').select2('val', '').trigger('change');
                jQuery('#auto_metaetiquetas').val('');
                return;
            }

            // Combinar texto base + etiquetas
            var textoFinal = textoBase.toUpperCase();
            //console.log(etiquetasSeleccionadas);

            if (etiquetasSeleccionadas && etiquetasSeleccionadas.length > 0) {
                var etiquetasAsignadas = etiquetasSeleccionadas.map(function(item) {
                    return item.text.toUpperCase();
                });

                textoFinal += separador + etiquetasAsignadas.join(separador);
                
                var valuesOrderEtiquetas = etiquetasSeleccionadas.map(function(item) {
                    return item.id;
                });

                jQuery('#auto_metaetiquetas').val(valuesOrderEtiquetas.join(","));
            }

            jQuery('#texto_compuesto').val(textoFinal);
        }
    });
</script>